Tree Traversals Implementation in Python

```python
# 1. In-Order: Left -> Root -> Right (Sorted order for BST)
def inorder(root: TreeNode) -> list[int]:
    return inorder(root.left) + [root.val] + inorder(root.right) if root else []

# 2. Pre-Order: Root -> Left -> Right (Good for serialization/copying)
def preorder(root: TreeNode) -> list[int]:
    return [root.val] + preorder(root.left) + preorder(root.right) if root else []

# 3. Post-Order: Left -> Right -> Root (Good for deletion/bottom-up calculations)
def postorder(root: TreeNode) -> list[int]:
    return postorder(root.left) + postorder(root.right) + [root.val] if root else []

# 4. Breadth-First Search (Level Order)
from collections import deque

def level_order(root: TreeNode) -> list[list[int]]:
    if not root: return []
    levels, queue = [], deque([root])
    while queue:
        level = []
        for _ in range(len(queue)):
            node = queue.popleft()
            level.append(node.val)
            if node.left: queue.append(node.left)
            if node.right: queue.append(node.right)
        levels.append(level)
    return levels
```

