Linked List Essential Operations in Python

```python
# Insert at Head: O(1)
def insert_head(head: ListNode, val: int) -> ListNode:
    return ListNode(val, head)

# Delete node with value target: O(n) search, O(1) unlink
def delete_node(head: ListNode, target: int) -> ListNode:
    dummy = ListNode(0, head)
    curr = dummy
    while curr.next:
        if curr.next.val == target:
            curr.next = curr.next.next
            break
        curr = curr.next
    return dummy.next

# Find Middle Node using Two Pointers: O(n)
def find_middle(head: ListNode) -> ListNode:
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
    return slow
```

memoization.pythonCode:
Manual LRU Cache in Python

```python
class Node:
    def __init__(self, key: int, val: int):
        self.key, self.val = key, val
        self.prev = self.next = None

class LRUCache:
    def __init__(self, capacity: int):
        self.cap = capacity
        self.cache = {} # key -> Node
        self.left, self.right = Node(0, 0), Node(0, 0)
        self.left.next = self.right
        self.right.prev = self.left

    def get(self, key: int) -> int:
        if key in self.cache:
            self.remove(self.cache[key])
            self.insert(self.cache[key])
            return self.cache[key].val
        return -1
```

